styleBlocks:
:root, :root[data-theme="light"] { --loading-bg: #ffffff; --loading-text: #09090b; --loading-logo: #a1a1aa; }
:root[data-theme="dark"], :root[data-theme="classic-dark"] { --loading-bg: #09090b; --loading-text: #fafafa; --loading-logo: #71717a; }
:root[data-theme="light-glass"] { --loading-bg: transparent; --loading-text: #09090b; --loading-logo: #a1a1aa; }
:root[data-theme="dark-glass"] { --loading-bg: #171716; --loading-text: #eeeeeb; --loading-logo: #71717a; }
:root[data-theme="classic-light"] { --loading-bg: #fafaf9; --loading-text: #171716; --loading-logo: #6e6e67; }
:root[data-theme="light-parchment"] { --loading-bg: #FAF9F6; --loading-text: #202116; --loading-logo: #6B665C; }
:root[data-theme="dark-parchment"] { --loading-bg: #1E1C18; --loading-text: #FAF9F6; --loading-logo: #8A857A; }
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; margin: 0px; background: var(--loading-bg); color: var(--loading-text); }
.loading-container { position: fixed; inset: 0px; display: flex; align-items: center; justify-content: center; background: var(--loading-bg); z-index: 9999; transition: opacity 150ms ease-out; }
#root:not(:empty) + .loading-container, #root:not(:empty) ~ .loading-container { opacity: 0; pointer-events: none; }
.loading-logo { width: 48px; height: 48px; object-fit: contain; }
.loading-logo-light { display: block; }
.loading-logo-dark { display: none; }
:root[data-theme="dark"] .loading-logo-light, :root[data-theme="dark-glass"] .loading-logo-light, :root[data-theme="classic-dark"] .loading-logo-light, :root[data-theme="dark-parchment"] .loading-logo-light { display: none; }
:root[data-theme="dark"] .loading-logo-dark, :root[data-theme="dark-glass"] .loading-logo-dark, :root[data-theme="classic-dark"] .loading-logo-dark, :root[data-theme="dark-parchment"] .loading-logo-dark { display: block; }

