/* Loading state before React loads - respects system theme */
:root,
:root[data-theme="light"] {
  --loading-bg: #ffffff;
  --loading-text: #09090b;
  --loading-logo: #a1a1aa;
}
:root[data-theme="dark"],
:root[data-theme="classic-dark"] {
  --loading-bg: #09090b;
  --loading-text: #fafafa;
  --loading-logo: #71717a;
}
/* light-glass 使用透明背景 */
:root[data-theme="light-glass"] {
  --loading-bg: transparent;
  --loading-text: #09090b;
  --loading-logo: #a1a1aa;
}
/* dark-glass 使用深色背景，首屏不偏白 */
:root[data-theme="dark-glass"] {
  --loading-bg: #171716;
  --loading-text: #eeeeeb;
  --loading-logo: #71717a;
}
/* classic-light 浅色加载 */
:root[data-theme="classic-light"] {
  --loading-bg: #fafaf9;
  --loading-text: #171716;
  --loading-logo: #6e6e67;
}
/* 羊皮纸浅色加载 */
:root[data-theme="light-parchment"] {
  --loading-bg: #FAF9F6;
  --loading-text: #202116;
  --loading-logo: #6B665C;
}
/* 羊皮纸暗色加载 */
:root[data-theme="dark-parchment"] {
  --loading-bg: #1E1C18;
  --loading-text: #FAF9F6;
  --loading-logo: #8A857A;
}
body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  margin: 0;
  background: var(--loading-bg);
  color: var(--loading-text);
}
/* Loading container - hidden when React renders */
.loading-container {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--loading-bg);
  z-index: 9999;
  transition: opacity 150ms ease-out;
}
/* Hide loading when root has content */
#root:not(:empty) + .loading-container,
#root:not(:empty) ~ .loading-container {
  opacity: 0;
  pointer-events: none;
}
.loading-logo {
  width: 48px;
  height: 48px;
  object-fit: contain;
}
.loading-logo-light { display: block; }
.loading-logo-dark { display: none; }
:root[data-theme="dark"] .loading-logo-light, :root[data-theme="dark-glass"] .loading-logo-light, :root[data-theme="classic-dark"] .loading-logo-light, :root[data-theme="dark-parchment"] .loading-logo-light { display: none; }
:root[data-theme="dark"] .loading-logo-dark, :root[data-theme="dark-glass"] .loading-logo-dark, :root[data-theme="classic-dark"] .loading-logo-dark, :root[data-theme="dark-parchment"] .loading-logo-dark { display: block; }

